-- Migration 046 — repair the 2026-08-25 RUMIYA plan-upload damage.
--
-- Cause (fixed in api.routes.js, same change set):
--   * the upload silently created line "B6 - RUMIYA" because the template's LINE CODE
--     matched no existing line, so the plan never reached B5 - RUMIYA;
--   * the line-detail upload ignored the template's PRODUCT CODE and wrote the
--     ACCORDIAN WALLET process list into whichever product the day's plan held,
--     destroying KN751 (17:29) and C2862 (17:34) shared process libraries.
--
-- This migration:
--   A. restores products 50 (C2862) and 52 (KN751) from the 2026-08-24 02:00 backup
--   B. clears the stray plan-workstation sets left on line 13 for 2026-08-25
--   C. moves the uploaded 88-workstation / 670-unit plan onto B5 - RUMIYA (line 13),
--      product 87 (CW781), work_date 2026-08-25
--   D. removes the accidental line 20 (B6 - RUMIYA) and duplicate product 89

BEGIN;

-- ---------------------------------------------------------------- A. restore libraries
-- The 17 rows the bad upload inserted into C2862 (ids 18308-18324) are referenced only
-- by line 13's stray 2026-08-25 set, which B drops. product_process_id is NO ACTION, so
-- the plan links must go first.
DELETE FROM line_plan_workstation_processes
 WHERE product_process_id IN (
     SELECT id FROM product_processes WHERE product_id = 50 AND id BETWEEN 18308 AND 18324
 );
DELETE FROM product_processes WHERE product_id = 50 AND id BETWEEN 18308 AND 18324;

