WHERE pp.id = v.id;


-- ---------------------------------------------------------------- B. clear strays
-- employee_workstation_assignments.line_plan_workstation_id is ON DELETE CASCADE, so
-- every delete of a plan workstation must detach the assignments first or it silently
-- takes the day's attendance with it.
UPDATE employee_workstation_assignments
   SET line_plan_workstation_id = NULL
 WHERE line_plan_workstation_id IN (
     SELECT id FROM line_plan_workstations
      WHERE line_id = 13 AND work_date = '2026-08-25' AND product_id IN (50, 52)
 );
DELETE FROM line_plan_workstations
 WHERE line_id = 13 AND work_date = '2026-08-25' AND product_id IN (50, 52);

-- ---------------------------------------------------------------- C. move the plan
-- C1. Rebuild product 87 (CW781) process list from the uploaded list now sitting under
--     product 89. Match by sequence_number and UPDATE in place so existing ids survive —
--     line 13's 2026-08-24 changeover plan links to them.
CREATE TEMP TABLE up_src ON COMMIT DROP AS
SELECT sequence_number, operation_id, operation_sah, cycle_time_seconds, osm_checked,
       group_name, workstation_code
  FROM product_processes
 WHERE product_id = 89 AND is_active;

UPDATE product_processes pp SET
    operation_id       = s.operation_id,
    operation_sah      = s.operation_sah,
    cycle_time_seconds = s.cycle_time_seconds,
    osm_checked        = s.osm_checked,
    group_name         = s.group_name,
    workstation_code   = s.workstation_code,
    is_active          = true,
    updated_at         = NOW()
FROM up_src s
WHERE pp.product_id = 87 AND pp.sequence_number = s.sequence_number;

INSERT INTO product_processes
    (product_id, operation_id, sequence_number, operation_sah, cycle_time_seconds,
     manpower_required, is_active, osm_checked, group_name, workstation_code)
SELECT 87, s.operation_id, s.sequence_number, s.operation_sah, s.cycle_time_seconds,
       1, true, s.osm_checked, s.group_name, s.workstation_code
  FROM up_src s
 WHERE NOT EXISTS (
     SELECT 1 FROM product_processes pp
      WHERE pp.product_id = 87 AND pp.sequence_number = s.sequence_number
 );

-- Sequence numbers beyond the uploaded list: deactivate, never delete, so the older
-- plan's links stay valid.
UPDATE product_processes
   SET is_active = false, updated_at = NOW()
 WHERE product_id = 87
   AND sequence_number NOT IN (SELECT sequence_number FROM up_src);

-- C2. Replace line 13's 2026-08-25 CW781 workstation set with the uploaded 88.
UPDATE employee_workstation_assignments
   SET line_plan_workstation_id = NULL
 WHERE line_plan_workstation_id IN (
     SELECT id FROM line_plan_workstations
      WHERE line_id = 13 AND work_date = '2026-08-25' AND product_id = 87
 );
DELETE FROM line_plan_workstations
 WHERE line_id = 13 AND work_date = '2026-08-25' AND product_id = 87;

INSERT INTO line_plan_workstations
    (line_id, work_date, product_id, workstation_number, workstation_code,
     takt_time_seconds, actual_sam_seconds, workload_pct, group_name)
SELECT 13, '2026-08-25', 87, src.workstation_number, src.workstation_code,
       src.takt_time_seconds, src.actual_sam_seconds, src.workload_pct, src.group_name
  FROM line_plan_workstations src
 WHERE src.line_id = 20 AND src.work_date = '2026-08-25' AND src.product_id = 89
 ORDER BY src.workstation_number;

-- C3. Copy the process breakdown, remapping product 89's process ids to product 87's
--     by sequence_number.
INSERT INTO line_plan_workstation_processes
    (workstation_id, product_process_id, sequence_in_workstation, osm_checked)
SELECT dst.id, dst_pp.id, src_lpwp.sequence_in_workstation, src_lpwp.osm_checked
  FROM line_plan_workstation_processes src_lpwp
  JOIN line_plan_workstations src ON src.id = src_lpwp.workstation_id
   AND src.line_id = 20 AND src.work_date = '2026-08-25' AND src.product_id = 89
  JOIN product_processes src_pp ON src_pp.id = src_lpwp.product_process_id
  JOIN product_processes dst_pp ON dst_pp.product_id = 87
   AND dst_pp.sequence_number = src_pp.sequence_number
  JOIN line_plan_workstations dst ON dst.line_id = 13 AND dst.work_date = '2026-08-25'
   AND dst.product_id = 87 AND dst.workstation_code = src.workstation_code;

-- C4. Re-point today's 74 employee assignments at the new workstation rows.
UPDATE employee_workstation_assignments e
   SET line_plan_workstation_id = w.id
  FROM line_plan_workstations w
 WHERE w.line_id = 13 AND w.work_date = '2026-08-25' AND w.product_id = 87
   AND e.line_id = 13 AND e.work_date = '2026-08-25' AND e.is_overtime = false
   AND e.workstation_code = w.workstation_code;

-- C5. Plan header: CW781 @ 670 on line 13 for the day.
UPDATE line_daily_plans
   SET product_id = 87, target_units = 670, updated_at = NOW()
 WHERE line_id = 13 AND work_date = '2026-08-25';

UPDATE production_lines
   SET current_product_id = 87, target_units = 670, updated_at = NOW()
 WHERE id = 13;

-- ---------------------------------------------------------------- D. remove the accident
-- Deleting the line cascades line_daily_plans, line_plan_workstations (and their
-- processes), line_workstations and employee_workstation_assignments for line 20.
DELETE FROM production_lines WHERE id = 20;
DELETE FROM product_processes WHERE product_id = 89;
DELETE FROM products WHERE id = 89;

COMMIT;
